// Block (composition) — a comment feed with loading, empty, and composer states.
// Stack owns arrangement; Avatar/Form/Textarea/Button/Separator own Component concerns, and SkeletonList owns loading content.
import { Fragment } from "react";
import type { FormEvent, ReactNode, Ref } from "react";
import { Avatar } from "../components/Avatar";
import { Button } from "../components/Button";
import { Form } from "../components/Form";
import { Separator } from "../components/Separator";
import { Stack } from "../layouts/Stack";
import { Textarea } from "../components/Textarea";
import { SkeletonList } from "./SkeletonList";
import "./CommentThread.css";

export interface CommentThreadProps {
  comments: {
    id: string;
    author: string;
    avatarSrc?: string;
    body: ReactNode;
    timestamp?: string;
  }[];
  onSubmit?: (body: string) => void;
  placeholder?: string;
  /** Renders skeleton placeholders while comments are loading. */
  isLoading?: boolean;
  /** Message shown above the composer when there are no comments. */
  emptyLabel?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function CommentThread({
  comments,
  onSubmit,
  placeholder = "Add a comment…",
  isLoading,
  emptyLabel = "No comments yet — start the conversation.",
  className,
  ref,
}: CommentThreadProps) {
  if (isLoading) {
    return <SkeletonList rows={3} showAvatar className={className} />;
  }
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const body = String(new FormData(event.currentTarget).get("comment") ?? "").trim();
    if (body) onSubmit?.(body);
    event.currentTarget.reset();
  };

  return (
    <Stack
      as="section"
      ref={ref}
      gap="medium"
      aria-label="Comments"
      className={className ? `sd-commentthread ${className}` : "sd-commentthread"}
    >
      {comments.length === 0 && (
        <p role="status" className="sd-commentthread__empty sd-type-caption-medium">
          {emptyLabel}
        </p>
      )}
      {comments.map((comment, index) => (
        <Fragment key={comment.id}>
          <Stack direction="row" gap="small" align="start" className="sd-commentthread__comment">
            <Avatar src={comment.avatarSrc} size="small" alt={comment.author}>
              {comment.author.charAt(0).toUpperCase()}
            </Avatar>
            <Stack gap="x-small" className="sd-commentthread__content">
              <Stack direction={{ small: "column", medium: "row" }} gap="x-small" align={{ medium: "center" }} className="sd-commentthread__meta">
                <strong className="sd-type-body-medium-emphasized">{comment.author}</strong>
                {comment.timestamp && (
                  <span className="sd-type-caption-medium">{comment.timestamp}</span>
                )}
              </Stack>
              {/* spacing: attachment — the byline names whose words follow */}
              <div className="sd-commentthread__body sd-type-body-medium">{comment.body}</div>
            </Stack>
          </Stack>
          {index < comments.length - 1 && <Separator />}
        </Fragment>
      ))}
      {comments.length > 0 && <Separator />}
      <Form onSubmit={handleSubmit}>
        <Stack gap="small" align="end" className="sd-commentthread__fields">
          <Textarea
            aria-label="Comment"
            name="comment"
            placeholder={placeholder}
            rows={3}
            isRequired
            className="sd-commentthread__composer"
          />
          <Button type="submit">Comment</Button>
        </Stack>
      </Form>
    </Stack>
  );
}

.sd-commentthread {
  width: 100%;
}

.sd-commentthread__content {
  flex: 1;
  min-width: 0;
}

.sd-commentthread__body {
  overflow-wrap: anywhere;
}

.sd-commentthread__composer {
  width: 100%;
}

/* empty state — layout only (muted color inherits default; blocks own no color) */
.sd-commentthread__empty {
  padding: var(--sd-space-large);
  text-align: center;
}
